<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue';
import AttachmentView from './AttachmentView.vue';
import { api, uploadMedia } from '../api';
import { type Row, formatTime } from '../../shared/domain';
import { useChat, chatStates } from '../../shared/useChat';
import Icon from './Icon.vue';
const props = defineProps<{ user: Row | null; target?: Row | null }>();
const emit = defineEmits<{ (event: 'join'): void; (event: 'clear-target'): void }>();
const { attachment, rooms, groups, people, active, messages, draft, error, busy, loading, hasMore, canSend, select, detail, action, send, recall, loadPeople, create, back } = useChat(() => props.user, api);
const uploading = ref(false);
async function attach(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0], room = active.value?.id, userId = props.user?.id;if (!file || !room) return;uploading.value = true;error.value = '';try { const row = await uploadMedia(file, 'chat', room);if (active.value?.id === room && props.user?.id === userId) attachment.value = row; } catch(e) { error.value = (e as Error).message; } finally { uploading.value = false;input.value = ''; } }
const tab = ref('chats'), query = ref(''), dialog = ref<HTMLDialogElement | null>(null), kind = ref(''), form = ref<Row>({}), messageList = ref<HTMLElement | null>(null);
const visible = computed(() => (tab.value === 'groups' ? groups.value : rooms.value).filter(r => r.title?.includes(query.value)));
const staff = computed(() => props.user && ['superadmin', 'admin', 'organizer'].includes(props.user.role));
async function open(value: string) { if (props.user?.status !== 'approved') { emit('join');return; }kind.value = value;form.value = value === 'direct' ? { recipientId: props.target?.id || '', content: '' } : { title: '', description: '' };await loadPeople();await nextTick();dialog.value?.showModal(); }
function close() { if (busy.value) return;dialog.value?.close();kind.value = '';emit('clear-target'); }
async function submit() { if (await create(kind.value, form.value)) close(); }
function confirmAction(actionName: string) { kind.value = 'confirm';form.value = { action: actionName };dialog.value?.showModal(); }
async function confirmed() { if (active.value) await action(active.value.id, form.value.action);close(); }
function canRecall(row: Row) { return !row.recalled && row.senderId === props.user?.id && Date.now() - new Date(row.createdAt).getTime() < 120000; }
watch(() => messages.value[messages.value.length - 1]?.id, async () => { await nextTick();messageList.value?.scrollTo({ top: messageList.value.scrollHeight, behavior: 'smooth' }); });
watch(() => props.target, target => { if (target) open('direct'); }, { immediate: true });
watch(() => props.user?.id, () => { dialog.value?.close();kind.value = '';form.value = {}; });
</script>
<template>
  <div v-if="user?.status !== 'approved'" class="empty"><Icon name="people"/><h3>聊一聊，乡情就近了</h3><p>审核通过的会员可以申请私聊、自愿加入群聊。</p><button class="primary" @click="emit('join')">登录 / 查看入会状态</button></div>
  <section v-else class="chat-shell" :class="{ 'chat-open': active }">
    <aside class="chat-sidebar"><div class="chat-side-title"><h2>家里的消息</h2><button class="chat-new" title="发起私聊" aria-label="发起私聊" @click="open('direct')">＋</button></div><div class="chat-tabs"><button :class="{ selected: tab === 'chats' }" @click="tab = 'chats'">我的会话</button><button :class="{ selected: tab === 'groups' }" @click="tab = 'groups'">发现群聊</button></div><label class="chat-search"><Icon name="search"/><input v-model="query" aria-label="搜索会话" placeholder="搜索老乡或群聊"></label><button v-if="staff && tab === 'groups'" class="outline full" @click="open('group')">创建群聊</button><p v-if="!visible.length" class="chat-list-empty">{{ tab === 'groups' ? '群聊还在准备中，欢迎常来看看。' : '一声问候，让彼此熟悉起来。' }}</p><button v-for="room in visible" :key="room.id" class="conversation" :class="{ selected: room.id === active?.id }" @click="room.joined ? select(room) : action(room.id, 'join')"><span class="chat-avatar" :class="{ group: room.type === 'group' }">{{ room.type === 'group' ? '群' : room.title?.slice(0,1) }}</span><span class="conversation-text"><b>{{ room.title }}</b><small>{{ tab === 'groups' ? room.memberCount + '位老乡 · ' + (room.joined ? '已加入' : '点击自愿加入') : room.preview || chatStates[room.status] }}</small></span><span v-if="room.unread" class="unread-badge">{{ room.unread > 99 ? '99+' : room.unread }}</span></button><p class="chat-list-note">群聊记录对加入的会员可见。<br>请尊重彼此，不在群内发布敏感资料。</p></aside>
    <div class="chat-main"><p v-if="error" class="form-error" role="alert">{{ error }}</p><template v-if="active"><header class="chat-header"><button class="chat-back" aria-label="返回会话列表" @click="back">‹</button><span class="chat-avatar">{{ active.type === 'group' ? '群' : active.title?.slice(0,1) }}</span><div><h3>{{ active.title }}</h3><small>{{ active.type === 'group' ? active.memberCount + '位老乡 · ' : '会员私聊 · ' }}{{ chatStates[active.status] }}</small></div><div class="chat-tools"><button v-if="active.type === 'direct' && active.status !== 'blocked'" @click="confirmAction('block')">屏蔽</button><button v-if="active.blockedBy === user?.id" @click="confirmAction('unblock')">恢复会话</button><button v-if="active.type === 'group' && active.ownerId !== user?.id" @click="confirmAction('leave')">退出群聊</button><button v-if="active.type === 'group' && active.ownerId === user?.id && active.status === 'active'" @click="confirmAction('close')">结束群聊</button></div></header>
      <div v-if="active.status === 'pending'" class="chat-request"><span>{{ active.requesterId === user?.id ? '问候已送达，等待对方接受后可以继续聊天。' : '这位老乡希望与你聊天，是否接受？' }}</span><div class="button-row"><template v-if="active.requesterId !== user?.id"><button class="primary small" :disabled="busy" @click="action(active.id, 'accept')">接受聊天</button><button class="outline small" :disabled="busy" @click="action(active.id, 'reject')">暂不接受</button></template><button v-else class="text-button" :disabled="busy" @click="action(active.id, 'cancel')">取消申请</button></div></div>
      <div ref="messageList" class="chat-messages"><button v-if="hasMore" class="older-messages" :disabled="loading" @click="detail(active.id, true)">查看更早的消息</button><p v-if="!messages.length" class="chat-list-empty">在这里，说一声老乡好。</p><article v-for="row in messages" :key="row.id" class="message" :class="{ mine: row.senderId === user?.id, recalled: row.recalled }"><template v-if="row.recalled"><p>一条消息已撤回</p></template><template v-else><span class="chat-avatar">{{ row.senderName?.slice(0,1) }}</span><div class="message-content"><small>{{ row.senderId === user?.id ? '我' : row.senderName }} · {{ formatTime(row.createdAt) }}</small><AttachmentView v-if="row.attachment" :attachment="row.attachment"/><p v-if="row.content">{{ row.content }}</p><button v-if="canRecall(row)" class="recall" :disabled="busy" @click="recall(row)">撤回</button></div></template></article></div>
      <form v-if="canSend" class="chat-composer" @submit.prevent="send"><div class="chat-attach-tools"><label>＋ 图片<input type="file" accept="image/jpeg,image/png" :disabled="busy || uploading" @change="attach"></label><label>拍照<input type="file" accept="image/jpeg,image/png" capture="environment" :disabled="busy || uploading" @change="attach"></label><label>＋ 文件<input type="file" accept=".pdf,.txt,.docx,.xlsx,.pptx,.zip" :disabled="busy || uploading" @change="attach"></label><small v-if="uploading">上传中…</small></div><div v-if="attachment" class="chat-pending"><span>{{ attachment.name }}</span><button type="button" :disabled="busy" @click="attachment = null">移除 ×</button></div><textarea :disabled="busy" v-model="draft" maxlength="2000" rows="2" aria-label="聊天消息" placeholder="说点什么，让乡情再近一点…" @keydown.ctrl.enter.prevent="send"></textarea><div><small>Ctrl + Enter 发送 · 最多2000字</small><button class="primary" :disabled="busy || uploading || (!draft.trim() && !attachment)">发送消息 <Icon name="arrow"/></button></div></form><div v-else class="chat-readonly">{{ active.peerAvailable === false ? '对方账号暂时无法接收消息' : chatStates[active.status] }}</div>
    </template><div v-else class="chat-welcome"><span class="chat-welcome-mark">聊</span><p class="eyebrow">A LITTLE CLOSER TO HOME</p><h2>熟悉的乡音，<br>从一声问候开始。</h2><p>和老乡聊近况，与伙伴商量活动。<br>留在家里的每句话，都值得被认真回应。</p><button class="primary" @click="open('direct')">找位老乡聊一聊 <Icon name="arrow"/></button></div></div>
    <dialog ref="dialog" class="modal" aria-label="聊天操作" @cancel.prevent="close"><div class="modal-inner"><header><h2>{{ kind === 'direct' ? '向老乡打个招呼' : kind === 'group' ? '创建老乡群聊' : '确认聊天操作' }}</h2><button class="close-button" aria-label="关闭聊天操作" :disabled="busy" @click="close">×</button></header><p v-if="error" class="form-error">{{ error }}</p><form v-if="kind !== 'confirm'" @submit.prevent="submit"><template v-if="kind === 'direct'"><label>选择老乡<select v-model="form.recipientId" required><option disabled value="">从自愿公开名录的会员中选择</option><option v-for="person in people" :key="person.id" :value="person.id">{{ person.name }} · {{ person.district }}</option></select></label><label>说声你好，说明来意<textarea v-model="form.content" required minlength="5" maxlength="500" rows="4"></textarea></label><p class="form-tip">对方接受后才能继续聊天，不会自动分享手机号或微信号。</p></template><template v-else><label>群聊名称<input v-model="form.title" required minlength="2" maxlength="50"></label><label>群聊介绍<textarea v-model="form.description" maxlength="500" rows="4"></textarea></label><p class="form-tip">审核会员可自愿加入；群聊记录对加入后的会员可见，每群最多200人。</p></template><button class="primary full" :disabled="busy">{{ kind === 'direct' ? '发送聊天申请' : '创建群聊' }}</button></form><div v-else><p class="prose">{{ form.action === 'block' ? '屏蔽后，双方都不能继续发送消息，已有记录保留。你可以恢复会话。' : form.action === 'leave' ? '退出后无法查看群聊记录；可从发现群聊重新加入。' : form.action === 'close' ? '结束后停止发送新消息，已加入的会员仍可查看记录。' : '确认恢复此会话？' }}</p><button class="primary full" :disabled="busy" @click="confirmed">确认操作</button></div></div></dialog>
  </section>
</template>
<style scoped>
.chat-shell{display:grid;grid-template-columns:290px minmax(0,1fr);height:720px;max-height:calc(100dvh - 205px);min-height:480px;border:1px solid #e8e3da;background:white;border-radius:22px;overflow:hidden}.chat-sidebar{border-right:1px solid #eee9e1;padding:24px 16px;overflow:auto;background:#fcfbf8}.chat-side-title{display:flex;align-items:center;justify-content:space-between;padding:0 8px}.chat-side-title h2{font-size:19px}.chat-new{width:32px;height:32px;border-radius:10px;background:#e9dfca;color:#755b31;font-size:22px}.chat-tabs{display:flex;gap:4px;background:#eeebe5;padding:4px;border-radius:11px;margin:22px 0 16px}.chat-tabs button{flex:1;padding:9px;border-radius:8px;font-size:12px;color:#6e7479}.chat-tabs .selected{background:#fff;color:#1b354d;box-shadow:0 2px 8px #152e4110}.chat-search{display:flex;align-items:center;gap:9px;padding:10px 12px;background:white;border:1px solid #e7e2d9;border-radius:10px;margin-bottom:18px}.chat-search input{border:0;background:transparent;width:100%;font-size:12px;outline:0}.chat-search .icon{width:15px;flex-shrink:0}.conversation{display:flex;align-items:center;gap:12px;width:100%;padding:14px 10px;border-radius:12px;text-align:left;margin-bottom:4px}.conversation:hover{background:#f0ede6}.conversation.selected{background:#eaeff1}.chat-avatar{width:40px;height:40px;background:#e9e3d5;color:#86714b;border-radius:13px;display:flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0}.chat-avatar.group{background:#e5ebee;color:#416175}.conversation-text{min-width:0;flex:1}.conversation-text b{display:block;font-size:13px;margin-bottom:5px;color:#213c50}.conversation-text small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#7b858c;font-size:11px}.chat-list-empty,.chat-list-note{font-size:12px;color:#7e8588;line-height:1.9;text-align:center;padding:25px 8px}.chat-list-note{font-size:11px;margin-top:25px}.chat-main{display:flex;flex-direction:column;min-width:0;min-height:0;position:relative}.chat-header{display:flex;align-items:center;gap:12px;padding:20px 24px;border-bottom:1px solid #ece7de}.chat-header h3{font-size:16px;margin:0 0 5px}.chat-header small{font-size:11px;color:#7b858c}.chat-tools{margin-left:auto;display:flex;gap:12px}.chat-tools button{font-size:11px;color:#6d7a83}.chat-messages{flex:1;min-height:0;overflow:auto;padding:25px;background:#f8f7f3}.message{display:flex;gap:11px;margin-bottom:23px}.message .chat-avatar{width:32px;height:32px;font-size:13px;border-radius:10px}.message-content{max-width:75%;min-width:0}.message-content small{display:block;font-size:10px;color:#8a8b88;margin-bottom:7px}.message-content p{background:#fff;border:1px solid #e8e4db;border-radius:2px 14px 14px;padding:12px 16px;font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;margin:0}.message.mine{flex-direction:row-reverse}.message.mine .message-content{text-align:right}.message.mine p{background:#203f55;color:#fff;text-align:left;border-color:#203f55;border-radius:14px 2px 14px 14px}.recall{font-size:10px;color:#889298;padding-top:5px}.message.recalled{justify-content:center;color:#989c9d;font-size:11px}.chat-composer{padding:17px 24px;background:white;border-top:1px solid #eee7db}.chat-composer textarea{width:100%;border:0;outline:0;resize:none;font-size:14px;line-height:1.8;min-height:65px;color:#243c4d;background:white}.chat-composer>div{display:flex;align-items:center;justify-content:space-between;gap:8px}.chat-composer small{font-size:10px;color:#8b959b}.chat-request{background:#fff5df;padding:14px 22px;font-size:12px;color:#876e43;display:flex;align-items:center;gap:16px;justify-content:space-between}.chat-request .button-row{margin:0}.chat-readonly{padding:20px;text-align:center;font-size:12px;color:#7c858b;background:#f4f3ef}.older-messages{display:block;margin:0 auto 24px;font-size:11px;color:#658194}.chat-welcome{margin:auto;padding:50px;text-align:center}.chat-welcome-mark{display:flex;align-items:center;justify-content:center;background:#ede5d3;color:#967846;font:40px Georgia,serif;width:90px;height:90px;border-radius:28px;margin:0 auto 25px;transform:rotate(-6deg)}.chat-welcome h2{font-size:32px;line-height:1.5;margin:16px 0;color:#243f52}.chat-welcome>p:not(.eyebrow){line-height:2;color:#7f8585;font-size:13px;margin-bottom:28px}.chat-back{display:none}.chat-main>.form-error{margin:8px 15px}.unread-badge{background:#c87850;color:#fff;border-radius:12px;min-width:18px;padding:2px 5px;font-size:10px;text-align:center}
@media(max-width:1100px){.chat-shell{grid-template-columns:235px minmax(0,1fr)}.chat-header{padding:16px}.chat-tools{gap:8px}.chat-request{flex-wrap:wrap}}@media(max-width:700px){.chat-shell{display:block;max-height:none;min-height:0;height:calc(100dvh - 225px);border-radius:15px}.chat-sidebar{height:100%;border:0}.chat-main{display:none;height:100%}.chat-open .chat-sidebar{display:none}.chat-open .chat-main{display:flex}.chat-back{display:block;font-size:30px;width:18px}.chat-header .chat-avatar{display:none}.chat-header h3{font-size:14px}.chat-messages{padding:18px 12px}.message-content{max-width:80%}.chat-composer{padding:12px}.chat-composer small{display:none}.chat-composer>div{justify-content:flex-end}.chat-request{padding:12px}.chat-tools button{font-size:10px}.chat-composer .primary{padding:9px 15px}}
</style>

<style scoped>
/* Keep the composer reachable when the keyboard leaves a short viewport. */
.chat-header{flex-shrink:0}
.chat-main{overflow-y:auto}
@media(max-width:700px){.chat-shell{min-height:360px}}
</style>

<style scoped>.chat-attach-tools{display:flex;gap:15px;flex-wrap:wrap;margin-bottom:10px}.chat-attach-tools label{font-size:12px;color:#806e4b;cursor:pointer;margin:0}.chat-attach-tools input{position:absolute;width:1px;height:1px;opacity:0}.chat-pending{font-size:12px;background:#f4eddb;padding:8px;border-radius:8px;overflow-wrap:anywhere;margin-bottom:7px}.chat-pending button{font-size:12px;color:#8c674d}.chat-composer{flex-shrink:0}</style>
